(async () => {
  const getCfg = (k) => (window.ytcfg && ytcfg.get && ytcfg.get(k)) || null;
  let apiKey = getCfg('INNERTUBE_API_KEY');
  let clientVersion = getCfg('INNERTUBE_CLIENT_VERSION') || '2.20240501.00.00';
  if (!apiKey) {
    const html = await (await fetch('https://www.youtube.com/?hl=en&gl=US', {credentials:'include'})).text();
    apiKey = (html.match(/"INNERTUBE_API_KEY":"([^"]+)"/) || [])[1];
    clientVersion = (html.match(/"INNERTUBE_CLIENT_VERSION":"([^"]+)"/) || [])[1] || clientVersion;
  }
  if (!apiKey) return {error: 'Could not find YouTube API key'};
  const context = {client: {clientName: 'WEB', clientVersion, hl: 'en', gl: 'US'}};
  const walk = (obj, fn) => {
    if (!obj || typeof obj !== 'object') return;
    fn(obj);
    for (const v of Object.values(obj)) walk(v, fn);
  };
  const searchRes = await fetch('https://www.youtube.com/youtubei/v1/search?key=' + encodeURIComponent(apiKey), {
    method: 'POST', credentials: 'include', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({context, query: 'Dune: Part Two official trailer'})
  });
  const searchJson = await searchRes.json();
  const videos = [];
  walk(searchJson, (node) => {
    if (node.videoRenderer) {
      const vr = node.videoRenderer;
      const text = (x) => x?.simpleText || x?.runs?.map(r => r.text).join('') || '';
      videos.push({
        videoId: vr.videoId,
        title: text(vr.title),
        channel: text(vr.ownerText || vr.longBylineText || vr.shortBylineText),
        viewCountText: text(vr.viewCountText),
        published: text(vr.publishedTimeText)
      });
    }
  });
  const match = videos.find(v => /dune:\s*part two\s*\|\s*official trailer\s*$/i.test(v.title) && /warner bros/i.test(v.channel))
    || videos.find(v => /dune:\s*part two/i.test(v.title) && /official trailer/i.test(v.title) && /warner bros/i.test(v.channel))
    || {videoId: 'Way9Dexny3w', title: 'DUNE: PART TWO | OFFICIAL TRAILER', channel: 'Warner Bros. Pictures'};
  const playerRes = await fetch('https://www.youtube.com/youtubei/v1/player?key=' + encodeURIComponent(apiKey), {
    method: 'POST', credentials: 'include', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({context, videoId: match.videoId, contentCheckOk: true, racyCheckOk: true})
  });
  const playerJson = await playerRes.json();
  const vd = playerJson.videoDetails || {};
  const n = Number(vd.viewCount);
  return {
    videoId: match.videoId,
    title: vd.title || match.title,
    channel: vd.author || match.channel,
    viewCount: vd.viewCount || match.viewCountText,
    formattedViewCount: Number.isFinite(n) ? new Intl.NumberFormat('en-US').format(n) + ' views' : (vd.viewCount || match.viewCountText)
  };
})()
